n_to" value="<?= e($_SERVER['REQUEST_URI']??'/') ?>"><button class="card-favorite <?= $isCardFavorite?'is-active':'' ?>" type="submit" aria-label="<?= $isCardFavorite?'Favorilerden çıkar':'Favorilere ekle' ?>" title="<?= $isCardFavorite?'Favorilerden çıkar':'Favorilere ekle' ?>"><?= $isCardFavorite?'♥':'♡' ?></button></form><?php endif; ?><script type="application/json" class="card-gallery-data"><?= json_encode($cardImages,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE) ?></script></div><a class="stay-content" href="/villa/<?= e($p['slug']) ?>"><h3><?= e($p['title']) ?></h3><div class="muted"><?= e(trim(($p['district']??'').', '.($p['city']??''))) ?> · <?= (int)$p['max_guests'] ?> misafir</div><div class="rating-line"><?php if((int)($p['rating_count']??0)>0): ?><span class="rating-star">★</span><span class="rating-score"><?= number_format((float)$p['rating_average'],1,',','.') ?>/10</span><span><?= (int)$p['rating_count'] ?> değerlendirme</span><?php else: ?><span>Henüz değerlendirme yok</span><?php endif; ?></div><div class="stay-price"><strong><?= e(number_format((float)$p['base_nightly_price'],0,',','.')) ?> <?= e($p['currency']) ?></strong> / gece</div></a></article><?php endforeach; ?><?php endif; ?></div></div></section><?php endif; ?>
