<script>(function(){var b=document.getElementById('menuToggle'),n=document.getElementById('siteNavigation'),o=document.getElementById('menuOverlay');if(!b||!n||!o)return;function setOpen(open){n.classList.toggle('is-open',open);o.classList.toggle('is-open',open);document.body.classList.toggle('menu-open',open);b.setAttribute('aria-expanded',open?'true':'false');b.setAttribute('aria-label',open?'Menüyü kapat':'Menüyü aç');var openMark=b.querySelector('.menu-open-mark'),closeMark=b.querySelector('.menu-close-mark');if(openMark)openMark.hidden=open;if(closeMark)closeMark.hidden=!open}function close(){setOpen(false)}setOpen(false);b.addEventListener('click',function(){setOpen(!n.classList.contains('is-open'))});o.addEventListener('click',close);n.addEventListener('click',function(e){if(e.target.closest('a'))close()});document.addEventListener('keydown',function(e){if(e.key==='Escape')close()});window.addEventListener('resize',function(){if(window.innerWidth>760)close()})})();</script><script>(function(){document.querySelectorAll('[data-card-gallery]').forEach(function(card){var data=card.querySelector('.card-gallery-data'),image=card.querySelector('.card-gallery-image'),count=card.querySelector('.card-gallery-count');if(!data||!image)return;var images=[];try{images=JSON.parse(data.textContent||'[]')}catch(e){}var index=0;card.querySelectorAll('[data-gallery-step]').forEach(function(button){button.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();if(images.length<2)return;index=(index+Number(button.dataset.galleryStep)+images.length)%images.length;image.src=images[index];if(count)count.textContent=(index+1)+' / '+images.length})})})})();</script><script>(function(){var input=document.getElementById('homeDestination'),list=document.getElementById('homeDestinationOptions'),selected=document.getElementById('homeLocationId'),form=document.getElementById('homeSearch');if(!input||!list||!selected)return;var timer=null,items=[],active=-1,seq=0;function close(){list.hidden=true;list.innerHTML='';active=-1}function choose(item){input.value=item.label;selected.value=String(item.id);close();input.setCustomValidity('')}function render(rows){items=Array.isArray(rows)?rows:[];list.innerHTML='';active=-1;items.forEach(function(item,i){var row=document.createElement('div');row.className='location-suggestion';row.setAttribute('role','option');row.setAttribute('aria-selected','false');row.textContent=item.label;row.addEventListener('pointerdown',function(e){e.preventDefault();choose(item)});list.appendChild(row)});list.hidden=items.length===0}function search(q,id){fetch('<?= e(app_url('/locations/search')) ?>?q='+encodeURIComponent(q),{credentials:'same-origin',headers:{'Accept':'application/json'}}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(function(rows){if(id!==seq)return;render(rows)}).catch(function(){if(id===seq)close()})}input.addEventListener('input',function(){selected.value='';input.setCustomValidity('');var q=input.value.trim(),id=++seq;clearTimeout(timer);if(!q){items=[];close();return}timer=setTimeout(function(){search(q,id)},120)});input.addEventListener('focus',function(){if(items.length&&input.value.trim())list.hidden=false});input.addEventListener('keydown',function(e){if(list.hidden||!items.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;Array.from(list.children).forEach(function(el,i){el.classList.toggle('is-active',i===active)});list.children[active].scrollIntoView({block:'nearest'})}else if(e.key==='Enter'&&active>=0){e.preventDefault();choose(items[active])}else if(e.key==='Escape')close()});input.addEventListener('change',function(){var item=items.find(function(x){return x.label===input.value});if(item)choose(item)});input.addEventListener('blur',function(){setTimeout(function(){close()},120)});if(form)form.addEventListener('submit',function(e){if(input.value.trim()&&!selected.value){e.preventDefault();input.setCustomValidity('Lütfen açılan önerilerden bir lokasyon seçin.');input.reportValidity();input.focus()}})})();</script><script>(function(){var ci=document.getElementById('homeCheckIn'),co=document.getElementById('homeCheckOut'),ciText=document.getElementById('checkInDisplay'),coText=document.getElementById('checkOutDisplay');if(!ci||!co)return;var fmt=new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric'});function pretty(v){if(!v)return '';var p=v.split('-');return fmt.format(new Date(Number(p[0]),Number(p[1])-1,Number(p[2]),12))}function sync(){var d;if(ci.value){var p=ci.value.split('-');d=new Date(Number(p[0]),Number(p[1])-1,Number(p[2]),12);d.setDate(d.getDate()+1)}else{d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+1)}var min=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');co.min=min;if(co.value&&co.value<min)co.value='';ciText.textContent=ci.value?pretty(ci.value):'Giriş tarihi seçin';coText.textContent=co.value?pretty(co.value):'Çıkış tarihi seçin'}ci.addEventListener('change',sync);co.addEventListener('change',sync);ci.addEventListener('click',function(){if(ci.showPicker)try{ci.showPicker()}catch(e){}});co.addEventListener('click',function(){if(co.showPicker)try{co.showPicker()}catch(e){}});sync();var form=document.getElementById('homeSearch');form.addEventListener('submit',function(e){if(ci.value&&co.value&&co.value<=ci.value){e.preventDefault();alert('Çıkış tarihi giriş tarihinden sonra olmalıdır.');co.focus();}})})();</script><script>(function(){var field=document.getElementById('guestField'),trigger=document.getElementById('guestTrigger'),panel=document.getElementById('guestPopover'),hidden=document.getElementById('guestTotal'),summary=document.getElementById('guestSummary'),done=document.getElementById('guestDone');if(!field||!trigger||!panel)return;var counts={adults:2,children:0,infants:0};function render(){Object.keys(counts).forEach(function(k){document.getElementById(k+'Count').textContent=counts[k];panel.querySelector('[data-count="'+k+'"][data-step="-1"]').disabled=counts[k]<(k==='adults'?1:0)});var total=counts.adults+counts.children+counts.infants;hidden.value=total;var parts=[];if(counts.adults)parts.push(counts.adults+' yetişkin');if(counts.children)parts.push(counts.children+' çocuk');if(counts.infants)parts.push(counts.infants+' bebek');summary.textContent=parts.join(', ')}function positionPanel(){var r=trigger.getBoundingClientRect(),w=Math.min(Math.max(r.width,280),window.innerWidth-24),left=Math.max(12,Math.min(r.left,window.innerWidth-w-12));panel.style.position='fixed';panel.style.top=Math.max(12,Math.min(r.bottom+8,window.innerHeight-250))+'px';panel.style.left=left+'px';panel.style.right='auto';panel.style.bottom='auto';panel.style.width=w+'px';panel.style.maxHeight='min(360px, calc(100vh - 24px))';panel.style.overflowY='auto';panel.style.zIndex='99999'}function open(){document.body.appendChild(panel);panel.hidden=false;positionPanel();trigger.setAttribute('aria-expanded','true')}function close(){panel.hidden=true;trigger.setAttribute('aria-expanded','false');field.appendChild(panel);panel.removeAttribute('style')}trigger.addEventListener('click',function(){if(panel.hidden)open();else close()});panel.querySelectorAll('[data-count]').forEach(function(btn){btn.addEventListener('click',function(){var k=btn.dataset.count,total=counts.adults+counts.children+counts.infants;if(btn.dataset.step==='1'&&total>=16)return;counts[k]=Math.max(k==='adults'?1:0,Math.min(16,counts[k]+Number(btn.dataset.step)));render();positionPanel()})});done.addEventListener('click',close);document.addEventListener('click',function(e){if(!field.contains(e.target)&&!panel.contains(e.target))close()});document.addEventListener('keydown',function(e){if(e.key==='Escape')close()});window.addEventListener('resize',function(){if(!panel.hidden)positionPanel()});window.addEventListener('scroll',function(){if(!panel.hidden)positionPanel()},true);render()})();</script><?php \App\Core\ThemeManager::renderPartial('partials/login-modal.php', get_defined_vars()); ?></body></html>